package edu.pe.cibertec.saibm.membresia.application;
import static org.assertj.core.api.Assertions.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test; import edu.pe.cibertec.saibm.membresia.application.port.in.*; import edu.pe.cibertec.saibm.membresia.application.port.out.*; import edu.pe.cibertec.saibm.membresia.application.usecase.*; import edu.pe.cibertec.saibm.membresia.domain.event.*; import edu.pe.cibertec.saibm.membresia.domain.model.*;
class MembershipUseCaseTest {
 @Test void assignmentReplayIsIdempotentAndConflictingPayloadFails(){var s=new Store();var use=new MembershipService(s);var p=use.createPlan(new MembershipUseCase.PlanCommand("standard","Standard",3,Instant.now().minusSeconds(1),null));var c=new MembershipUseCase.AssignmentCommand("user-1",p.id(),Instant.now(),null);var first=use.assign(c,"same-key","c1");var replay=use.assign(c,"same-key","c1");assertThat(replay).isEqualTo(first);assertThat(s.events).hasSize(2);assertThatThrownBy(()->use.assign(new MembershipUseCase.AssignmentCommand("user-1",p.id(),c.validFrom(),Instant.now().plusSeconds(9)),"same-key","c1")).isInstanceOf(IllegalStateException.class);}
 @Test void expiredAssignmentReturnsIneligibleSnapshot(){var s=new Store();var use=new MembershipService(s);var p=use.createPlan(new MembershipUseCase.PlanCommand("short","Short",9,Instant.now().minusSeconds(10),Instant.now().plusSeconds(1)));use.assign(new MembershipUseCase.AssignmentCommand("user-2",p.id(),Instant.now().minusSeconds(1),Instant.now().plusSeconds(1)),"k2","c2");assertThat(use.entitlement("user-2",Instant.now().plusSeconds(2)).eligible()).isFalse();}
 @Test void changedAndExpiredAssignmentsPublishVersionedEvents(){var s=new Store();var use=new MembershipService(s);var from=Instant.now().minusSeconds(1);var p1=use.createPlan(new MembershipUseCase.PlanCommand("a","A",2,from,null));var p2=use.createPlan(new MembershipUseCase.PlanCommand("b","B",6,from,null));use.assign(new MembershipUseCase.AssignmentCommand("user-3",p1.id(),from,Instant.now().plusSeconds(1)),"k3","c3");use.assign(new MembershipUseCase.AssignmentCommand("user-3",p2.id(),from,Instant.now().plusSeconds(1)),"k4","c4");use.expireDue(Instant.now().plusSeconds(2),"c5");assertThat(s.events).extracting(MembershipEvent::eventType).contains("MembershipAssigned.v1","MembershipChanged.v1","MembershipExpired.v1","PlanUpdated.v1");}
 static final class Store implements MembershipStorePort {final Map<UUID,Plan> plans=new HashMap<>();final Map<String,MembershipAssignment> assignments=new HashMap<>();final List<MembershipEvent> events=new ArrayList<>();final List<MembershipHistory> history=new ArrayList<>();public Optional<Plan> plan(UUID id){return Optional.ofNullable(plans.get(id));}public List<Plan> activePlans(Instant at){return plans.values().stream().filter(p->p.validAt(at)).toList();}public Optional<MembershipAssignment> assignmentByKey(String k){return Optional.ofNullable(assignments.get(k));}public Optional<MembershipAssignment> activeAssignment(String u,Instant at){return assignments.values().stream().filter(a->a.userId().equals(u)&&a.validAt(at)).findFirst();}public int insert(MembershipAssignment a){if(assignments.containsKey(a.idempotencyKey()))return 0;assignments.put(a.idempotencyKey(),a);return 1;}public void save(Plan p){plans.put(p.id(),p);}public void save(MembershipAssignment a){assignments.put(a.idempotencyKey(),a);}public void history(MembershipHistory h){history.add(h);}public List<MembershipHistory> history(String u){return history.stream().filter(h->h.userId().equals(u)).toList();}public List<MembershipAssignment> expiring(Instant at){return assignments.values().stream().filter(a->a.active()&&a.validUntil()!=null&&!a.validUntil().isAfter(at)).toList();}public void outbox(MembershipEvent e){events.add(e);}}
}
